import type { CostBreakdown } from './cost.js';
import type { ProviderName } from './provider.js';
import type { TokenUsage } from './usage.js';

/**
 * Represents one tracked AI provider request.
 */
export interface UsageEvent {
  /** Unique ID generated by TokenTrack. */
  id: string;

  /** AI provider associated with this request. */
  provider: ProviderName;

  /** Model used for the request, e.g. gpt-4o or claude-sonnet. */
  model: string;

  /** Normalized token usage reported by the provider. */
  usage: TokenUsage;

  /** Request timestamp in ISO 8601 format. */
  timestamp: string;

  /** Provider-generated request ID, when available. */
  requestId?: string;

  /** Application operation associated with this request. */
  operationId?: string;

  /** Observable attempt number within a retry sequence. */
  attemptNumber?: number;

  /** Request duration in milliseconds, when available. */
  durationMs?: number;

  /** Whether the request used streaming. */
  streaming?: boolean;

  /** Estimated and provider-reported cost information. */
  cost?: CostBreakdown;
}